input.sparql:
SELECT ?zone ?sensor WHERE {
  ?zone a brick:Zone ; brick:hasName ?zoneName .
  FILTER(?zoneName IN ("Core_mid","Perimeter_mid_ZN_3","Perimeter_top_ZN_3"))
  ?sensor brick:hasSensorOutput ?zone .
  ?sensor a brick:ElectricPowerSensor .
}

SELECT ?zone ?name WHERE {
  ?zone a brick:Zone .
  ?zone rdfs:label ?name .
  FILTER(?name IN ("Core_mid","Perimeter_mid_ZN_3","Perimeter_top_ZN_3"))
}

SELECT DISTINCT ?cls WHERE {
  ?z a ?cls .
  ?z a brick:Zone .
}

