import csv
from collections import defaultdict

wanted = {
    "Core_mid": "95a195d5-d0ce-5098-bcec-ca1a2e9c4f28",
    "Perimeter_mid_ZN_3": "49eac0ff-63d2-57a8-90a0-fdee8aaf25a6",
    "Perimeter_top_ZN_3": "66009ccf-dd88-5be4-87fd-ed38ec990e48",
}

sids = set(wanted.values())
day = "2018-10-04"
sums = defaultdict(float)
counts = defaultdict(int)

with open(VALUES_CSV) as f:
    for row in csv.DictReader(f):
        if row["timeseries_id"] in sids:
            if row["timestamp"].startswith(day):
                try:
                    sums[row["timeseries_id"]] += float(row["value"])
                    counts[row["timeseries_id"]] += 1
                except ValueError:
                    pass

for zone, sid in wanted.items():
    print(zone, "sum_W=", sums[sid], "n=", counts[sid], "kWh=", sums[sid]/1000.0)
